mixed=[Q('سه باکتری رشته‌ای این فایل را مقایسه کنید.','اکتینومایسس عمدتاً درون‌زاد و بی‌هوازی یا کم‌اکسیژن‌دوست است؛ نوکاردیا و استرپتومایسس محیطی و هوازی‌اند. نوکاردیا اسیدفست نسبی و درگیری ریه/انتشار دارد؛ استرپتومایسس با تولید دارو و مایستوما مطرح است.',['منشأ','اکسیژن','اسیدفست','بیماری'],[3,4,5,6]),Q('سه عامل تنفسی را از نظر زیستگاه و توان مهم مقایسه کنید.','هموفیلوس حضور مخاطی و کپسول/نیاز X و V دارد؛ لژیونلا محیط آبی و بقای فاگوسیتی؛ بوردتلا عامل انسانی سیاه‌سرفه با سم و آسیب مژک است.',['زیستگاه','عامل شاخص','پیامد'],[8,9,10,11,12,13]),Q('چرا ناقل‌بودن لزوماً بیماری نیست؟','محل، تعادل زیستی و دفاع مهم‌اند؛ ورود به خون یا عمق بافت می‌تواند تعادل را تغییر دهد. پادتن یا حضور عامل به‌تنهایی برای انتساب بیماری کافی نیست.',['محل','دفاع','تغییر زمینه'],[3,10,11])]
source=[Q('چرا هموفیلوس با وجود عوامل بیماری‌زایی، میکروبیوتای طبیعی باقی می‌ماند؟','وجود عوامل بیماری‌زایی به معنی بیماری در هر محل و هر زمان نیست. سد مخاطی، دفاع میزبان و رقابت میکروبی می‌توانند باکتری را در محل طبیعی محدود کنند؛ ورود به خون یا تغییر دفاع، این تعادل را تغییر می‌دهد.',['تعادل','محل','محدودیت'],[10,11],'سؤال ۱ خود جزوه'),Q('با نبود X و V آزاد در مخاط، رشد چگونه توضیح داده شده است؟','در مثال جزوه، میکروب‌های همراه و فرآورده‌های میزبان می‌توانند عوامل رشد را فراهم کنند. نکتهٔ اصلی، وابستگی هموفیلوس به‌دسترسی به مواد لازم است؛ نیاز تغذیه‌ای و وجود این مواد در محیط دو موضوع مرتبط‌اند.',['همکاری','محدودیت رشد','دسترسی به عامل رشد'],[11],'سؤال ۲ خود جزوه')]
